¶hw-eval/src/benchmarks/submission_bottleneck/experiment_1_submit_occupancy.rs#C58A
1:// Experiment 1: occupancy-conditioned submit trace.
2://
3:// Logical operations are submitted one per MMIO. Each iteration pre-submits K
4:// descriptors, then records raw timing for the measured submit range:
5://
6://   default: [op 0] ... [op K-1] + [op K]
7://                         prefill     measured
8://
9://   trace-until N: [op 0] ... [op K-1] + [op K] ... [op N-1]
10://                              prefill     measured submit trace
11://
12:// Statistics are deliberately left to post-processing so plotting can choose
13:// percentiles and filters without changing the hardware runner.
14://
15:
16:use hw_eval::dsa::{
17:    completion_flags_no_cache_control, poll_completion, reset_completion, DsaCompletionRecord,
18:    DsaHwDesc, DSA_COMP_SUCCESS,
19:};
20:use hw_eval::submit::{cycles_to_ns, rdtscp, WqPortal};
21:
22:use crate::config::DsaOperationClass;
23:use crate::report::{
24:    SubmitOccupancyExtraTracePoint, SubmitOccupancyPrefillCompletionTracePoint,
25:    SubmitOccupancyResult, SubmitOccupancyTraceOutcome,
26:};
27:
28:use super::common::{
29:    count_visible_completions, reset_sample_completions, scan_visible_completions, OperationSlots,
30:};
31:
32:const SUBMIT_OCCUPANCY_BENCHMARK: &str = "submit_occupancy_trace";
33:
34:pub(crate) fn bench_submit_occupancy_one_extra(
35:    wq: &WqPortal,
36:    occupancies: &[usize],
37:    operation: DsaOperationClass,
38:    payload_size: usize,
39:    trace_until: Option<usize>,
40:    iterations: usize,
41:    tsc_freq: u64,
42:    json: bool,
43:    results: &mut Vec<SubmitOccupancyResult>,
44:) {
45:    let Some(max_submitted) = occupancies
46:        .iter()
47:        .map(|&k_prefill| submitted_count(k_prefill, trace_until))
48:        .max()
49:    else {
50:        return;
51:    };
52:
53:    let mut slots = OperationSlots::new_with_payload(max_submitted, operation, payload_size);
54:    let mut seen = vec![false; max_submitted];
55:    let mut sentinel_comp = DsaCompletionRecord::default();
56:    let operation_class = operation.operation_class_label(payload_size);
57:
58:    if !json {
59:        print_trace_header(&operation_class);
60:    }
61:
62:    for &k_prefill in occupancies {
63:        let submitted = submitted_count(k_prefill, trace_until);
64:        let mut prefill_completion_trace = Vec::with_capacity(iterations);
65:        let mut trace = Vec::with_capacity(iterations * (submitted - k_prefill));
66:        let mut outcomes = Vec::with_capacity(iterations);
67:
68:        for iteration_index in 0..iterations {
69:            reset_sample_completions(&mut slots.completions[..submitted]);
70:
71:            for desc in &slots.descriptors[..k_prefill] {
72:                unsafe { wq.submit(desc) };
73:            }
74:
75:            for submit_index in k_prefill..submitted {
76:                let start_tsc = rdtscp().0;
77:                unsafe { wq.submit(&slots.descriptors[submit_index]) };
78:                let submit_tsc_ticks = rdtscp().0 - start_tsc;
79:                trace.push(SubmitOccupancyExtraTracePoint {
80:                    iteration_index,
81:                    submit_index,
82:                    submit_tsc_ticks,
83:                    submit_ns: cycles_to_ns(submit_tsc_ticks, tsc_freq),
84:                });
85:            }
86:
87:            let bounded_outcome =
88:                count_visible_completions(&slots.completions[..submitted], &mut seen[..submitted]);
89:
90:            drain_with_sentinel(wq, &mut sentinel_comp, operation, payload_size, k_prefill);
91:
92:            let outcome = if bounded_outcome.completed == submitted {
93:                bounded_outcome
94:            } else {
95:                scan_visible_completions(&slots.completions[..submitted])
96:            };
97:
98:            outcomes.push(SubmitOccupancyTraceOutcome {
99:                iteration_index,
100:                completed: outcome.completed,
101:                missing: submitted - outcome.completed,
102:                errors: outcome.errors,
103:            });
104:
105:            let prefill_completion = measure_prefill_completion(
106:                wq,
107:                &slots.descriptors[..k_prefill],
108:                &mut slots.completions[..k_prefill],
109:                &mut seen[..k_prefill],
110:                tsc_freq,
111:                iteration_index,
112:            );
113:            prefill_completion_trace.push(prefill_completion);
114:            if k_prefill > 0 {
115:                drain_with_sentinel(wq, &mut sentinel_comp, operation, payload_size, k_prefill);
116:            }
117:        }
118:
119:        let result = SubmitOccupancyResult {
120:            benchmark: SUBMIT_OCCUPANCY_BENCHMARK.to_string(),
121:            operation_class: operation_class.clone(),
122:            k_prefill,
123:            submitted,
124:            trace_until: submitted,
125:            prefill_completion_trace,
126:            extra_submit_trace: trace,
127:            trace_outcomes: outcomes,
128:        };
129:
130:        if !json {
131:            print_trace_row(&result);
132:        }
133:        results.push(result);
134:    }
135:}
136:
137:fn submitted_count(k_prefill: usize, trace_until: Option<usize>) -> usize {
138:    trace_until.unwrap_or(k_prefill + 1).max(k_prefill + 1)
139:}
140:
141:fn measure_prefill_completion(
142:    wq: &WqPortal,
143:    descriptors: &[DsaHwDesc],
144:    completions: &mut [DsaCompletionRecord],
145:    seen: &mut [bool],
146:    tsc_freq: u64,
147:    iteration_index: usize,
148:) -> SubmitOccupancyPrefillCompletionTracePoint {
149:    reset_sample_completions(completions);
150:
151:    if descriptors.is_empty() {
152:        return SubmitOccupancyPrefillCompletionTracePoint {
153:            iteration_index,
154:            prefill_submit_tsc_ticks: 0,
155:            prefill_submit_ns: 0,
156:            prefill_completion_tsc_ticks: 0,
157:            prefill_completion_ns: 0,
158:            post_submit_completion_tsc_ticks: 0,
159:            post_submit_completion_ns: 0,
160:            completed: 0,
161:            missing: 0,
162:            errors: 0,
163:        };
164:    }
165:
166:    let prefill_start_tsc = rdtscp().0;
167:    for desc in descriptors {
168:        unsafe { wq.submit(desc) };
169:    }
170:    let prefill_submit_tsc_ticks = rdtscp().0 - prefill_start_tsc;
171:
172:    let outcome = count_visible_completions(completions, seen);
173:    let prefill_completion_tsc_ticks = rdtscp().0 - prefill_start_tsc;
174:    let post_submit_completion_tsc_ticks =
175:        prefill_completion_tsc_ticks.saturating_sub(prefill_submit_tsc_ticks);
176:
177:    SubmitOccupancyPrefillCompletionTracePoint {
178:        iteration_index,
179:        prefill_submit_tsc_ticks,
180:        prefill_submit_ns: cycles_to_ns(prefill_submit_tsc_ticks, tsc_freq),
181:        prefill_completion_tsc_ticks,
182:        prefill_completion_ns: cycles_to_ns(prefill_completion_tsc_ticks, tsc_freq),
183:        post_submit_completion_tsc_ticks,
184:        post_submit_completion_ns: cycles_to_ns(post_submit_completion_tsc_ticks, tsc_freq),
185:        completed: outcome.completed,
186:        missing: completions.len() - outcome.completed,
187:        errors: outcome.errors,
188:    }
189:}
190:
191:fn drain_with_sentinel(
192:    wq: &WqPortal,
193:    sentinel_comp: &mut DsaCompletionRecord,
194:    operation: DsaOperationClass,
195:    payload_size: usize,
196:    k_prefill: usize,
197:) {
198:    let mut sentinel_desc = DsaHwDesc::default();
199:    sentinel_desc.fill_noop(completion_flags_no_cache_control());
200:    reset_completion(sentinel_comp);
201:    sentinel_desc.set_completion(sentinel_comp);
202:
203:    unsafe { wq.submit(&sentinel_desc) };
204:    let status = poll_completion(sentinel_comp);
205:    if status != DSA_COMP_SUCCESS {
206:        panic!(
207:            "DSA submit-occupancy drain sentinel failed: status {status:#x} \
208:             (operation={}, k_prefill={k_prefill})",
209:            operation.operation_class_label(payload_size)
210:        );
211:    }
212:}
213:
214:fn print_trace_header(operation_class: &str) {
215:    println!("\n=== {SUBMIT_OCCUPANCY_BENCHMARK} ({operation_class}) ===");
216:    println!(
217:        "{:>8} {:>10} {:>15} {:>12} {:>12}",
218:        "K", "submitted", "prefill_samples", "trace_points", "iterations"
219:    );
220:}
221:
222:fn print_trace_row(result: &SubmitOccupancyResult) {
223:    println!(
224:        "{:>8} {:>10} {:>15} {:>12} {:>12}",
225:        result.k_prefill,
226:        result.submitted,
227:        result.prefill_completion_trace.len(),
228:        result.extra_submit_trace.len(),
229:        result.trace_outcomes.len()
230:    );
231:}
