22:use crate::config::DsaOperationClass;
23:use crate::report::{
24:    SubmitOccupancyExtraTracePoint, SubmitOccupancyPrefillCompletionTracePoint,
25:    SubmitOccupancyResult, SubmitOccupancyTraceOutcome,
26:};
27:
28:use super::common::{
29:    count_visible_completions, reset_sample_completions, scan_visible_completions, OperationSlots,
30:};
31:
32:const SUBMIT_OCCUPANCY_BENCHMARK: &str = "submit_occupancy_trace";
33:
34:pub(crate) fn bench_submit_occupancy_one_extra(
35:    wq: &WqPortal,
36:    occupancies: &[usize],
37:    operation: DsaOperationClass,
38:    payload_size: usize,
39:    trace_until: Option<usize>,
40:    iterations: usize,
41:    tsc_freq: u64,
42:    json: bool,
43:    results: &mut Vec<SubmitOccupancyResult>,
44:) {
45:    let Some(max_submitted) = occupancies
46:        .iter()
47:        .map(|&k_prefill| submitted_count(k_prefill, trace_until))
48:        .max()
49:    else {
50:        return;
51:    };
52:
53:    let mut runner =
54:        SubmitOccupancyRunner::new(wq, max_submitted, operation, payload_size, tsc_freq);
55:
56:    if !json {
57:        print_trace_header(runner.operation_class());
58:    }
59:
60:    for &k_prefill in occupancies {
61:        let submitted = submitted_count(k_prefill, trace_until);
62:        let result = runner.collect_result(k_prefill, submitted, iterations);
63:
64:        if !json {
65:            print_trace_row(&result);
66:        }
67:        results.push(result);
68:    }
69:}
