75:struct SubmitOccupancyRunner<'a> {
76:    wq: &'a WqPortal,
77:    slots: OperationSlots,
78:    seen: Vec<bool>,
79:    sentinel_comp: DsaCompletionRecord,
80:    operation_class: String,
81:    tsc_freq: u64,
82:}
83:
84:impl<'a> SubmitOccupancyRunner<'a> {
85:    fn new(
86:        wq: &'a WqPortal,
87:        max_submitted: usize,
88:        operation: DsaOperationClass,
89:        payload_size: usize,
90:        tsc_freq: u64,
91:    ) -> Self {
92:        let operation_class = operation.operation_class_label(payload_size);
93:        let slots = OperationSlots::new_with_payload(max_submitted, operation, payload_size);
94:
95:        Self {
96:            wq,
97:            slots,
98:            seen: vec![false; max_submitted],
99:            sentinel_comp: DsaCompletionRecord::default(),
100:            operation_class,
101:            tsc_freq,
102:        }
103:    }
104:
105:    fn operation_class(&self) -> &str {
106:        &self.operation_class
107:    }
108:
109:    fn collect_result(
110:        &mut self,
111:        k_prefill: usize,
112:        submitted: usize,
113:        iterations: usize,
114:    ) -> SubmitOccupancyResult {
115:        let mut prefill_completion_trace = Vec::with_capacity(iterations);
116:        let mut extra_submit_trace = Vec::with_capacity(iterations * (submitted - k_prefill));
117:        let mut trace_outcomes = Vec::with_capacity(iterations);
118:
119:        for iteration_index in 0..iterations {
120:            self.run_iteration(
121:                k_prefill,
122:                submitted,
123:                iteration_index,
124:                &mut extra_submit_trace,
125:                &mut trace_outcomes,
126:                &mut prefill_completion_trace,
127:            );
128:        }
129:
130:        SubmitOccupancyResult {
131:            benchmark: SUBMIT_OCCUPANCY_BENCHMARK.to_string(),
132:            operation_class: self.operation_class.clone(),
133:            k_prefill,
134:            submitted,
135:            trace_until: submitted,
136:            prefill_completion_trace,
137:            extra_submit_trace,
138:            trace_outcomes,
139:        }
140:    }
141:
142:    fn run_iteration(
143:        &mut self,
144:        k_prefill: usize,
145:        submitted: usize,
146:        iteration_index: usize,
147:        extra_submit_trace: &mut Vec<SubmitOccupancyExtraTracePoint>,
148:        trace_outcomes: &mut Vec<SubmitOccupancyTraceOutcome>,
149:        prefill_completion_trace: &mut Vec<SubmitOccupancyPrefillCompletionTracePoint>,
150:    ) {
151:        reset_sample_completions(&mut self.slots.completions[..submitted]);
152:        submit_descriptors(self.wq, &self.slots.descriptors[..k_prefill]);
153:        self.trace_measured_submits(k_prefill, submitted, iteration_index, extra_submit_trace);
154:
155:        let outcome = self.completion_outcome(submitted, k_prefill, iteration_index);
156:        trace_outcomes.push(outcome);
157:
158:        let prefill_completion = self.measure_prefill_completion(k_prefill, iteration_index);
159:        prefill_completion_trace.push(prefill_completion);
160:        if k_prefill > 0 {
161:            self.drain(k_prefill);
162:        }
163:    }
164:
165:    fn trace_measured_submits(
166:        &self,
167:        k_prefill: usize,
168:        submitted: usize,
169:        iteration_index: usize,
170:        extra_submit_trace: &mut Vec<SubmitOccupancyExtraTracePoint>,
171:    ) {
172:        for submit_index in k_prefill..submitted {
173:            let start_tsc = rdtscp().0;
174:            unsafe { self.wq.submit(&self.slots.descriptors[submit_index]) };
175:            let submit_tsc_ticks = rdtscp().0 - start_tsc;
176:            extra_submit_trace.push(SubmitOccupancyExtraTracePoint {
177:                iteration_index,
178:                submit_index,
179:                submit_tsc_ticks,
180:                submit_ns: cycles_to_ns(submit_tsc_ticks, self.tsc_freq),
181:            });
182:        }
183:    }
184:
185:    fn completion_outcome(
186:        &mut self,
187:        submitted: usize,
188:        k_prefill: usize,
189:        iteration_index: usize,
190:    ) -> SubmitOccupancyTraceOutcome {
191:        let bounded_outcome = count_visible_completions(
192:            &self.slots.completions[..submitted],
193:            &mut self.seen[..submitted],
194:        );
195:
196:        self.drain(k_prefill);
197:
198:        let outcome = if bounded_outcome.completed == submitted {
199:            bounded_outcome
200:        } else {
201:            scan_visible_completions(&self.slots.completions[..submitted])
202:        };
203:
204:        SubmitOccupancyTraceOutcome {
205:            iteration_index,
206:            completed: outcome.completed,
207:            missing: submitted - outcome.completed,
208:            errors: outcome.errors,
209:        }
210:    }
211:
212:    fn measure_prefill_completion(
213:        &mut self,
214:        k_prefill: usize,
215:        iteration_index: usize,
216:    ) -> SubmitOccupancyPrefillCompletionTracePoint {
217:        measure_prefill_completion_trace(
218:            self.wq,
219:            &self.slots.descriptors[..k_prefill],
220:            &mut self.slots.completions[..k_prefill],
221:            &mut self.seen[..k_prefill],
222:            self.tsc_freq,
223:            iteration_index,
224:        )
225:    }
226:
227:    fn drain(&mut self, k_prefill: usize) {
228:        drain_with_sentinel(
229:            self.wq,
230:            &mut self.sentinel_comp,
231:            &self.operation_class,
232:            k_prefill,
233:        );
234:    }
235:}
