237:fn submit_descriptors(wq: &WqPortal, descriptors: &[DsaHwDesc]) {
238:    for desc in descriptors {
239:        unsafe { wq.submit(desc) };
240:    }
241:}
242:
243:fn empty_prefill_completion_trace_point(
244:    iteration_index: usize,
245:) -> SubmitOccupancyPrefillCompletionTracePoint {
246:    SubmitOccupancyPrefillCompletionTracePoint {
247:        iteration_index,
248:        prefill_submit_tsc_ticks: 0,
249:        prefill_submit_ns: 0,
250:        prefill_completion_tsc_ticks: 0,
251:        prefill_completion_ns: 0,
252:        post_submit_completion_tsc_ticks: 0,
253:        post_submit_completion_ns: 0,
254:        completed: 0,
255:        missing: 0,
256:        errors: 0,
257:    }
258:}
259:
260:fn measure_prefill_completion_trace(
261:    wq: &WqPortal,
262:    descriptors: &[DsaHwDesc],
263:    completions: &mut [DsaCompletionRecord],
264:    seen: &mut [bool],
265:    tsc_freq: u64,
266:    iteration_index: usize,
267:) -> SubmitOccupancyPrefillCompletionTracePoint {
268:    reset_sample_completions(completions);
269:
270:    if descriptors.is_empty() {
271:        return empty_prefill_completion_trace_point(iteration_index);
272:    }
273:
274:    let prefill_start_tsc = rdtscp().0;
275:    submit_descriptors(wq, descriptors);
276:    let prefill_submit_tsc_ticks = rdtscp().0 - prefill_start_tsc;
277:
278:    let outcome = count_visible_completions(completions, seen);
279:    let prefill_completion_tsc_ticks = rdtscp().0 - prefill_start_tsc;
280:    let post_submit_completion_tsc_ticks =
281:        prefill_completion_tsc_ticks.saturating_sub(prefill_submit_tsc_ticks);
282:
283:    SubmitOccupancyPrefillCompletionTracePoint {
284:        iteration_index,
285:        prefill_submit_tsc_ticks,
286:        prefill_submit_ns: cycles_to_ns(prefill_submit_tsc_ticks, tsc_freq),
287:        prefill_completion_tsc_ticks,
288:        prefill_completion_ns: cycles_to_ns(prefill_completion_tsc_ticks, tsc_freq),
289:        post_submit_completion_tsc_ticks,
