struct SubmitOccupancyRunner<'a> {
    wq: &'a WqPortal,
    slots: OperationSlots,
    seen: Vec<bool>,
    sentinel_comp: DsaCompletionRecord,
    operation_class: String,
    tsc_freq: u64,
}

impl<'a> SubmitOccupancyRunner<'a> {
    fn new(
        wq: &'a WqPortal,
        max_submitted: usize,
        operation: DsaOperationClass,
        payload_size: usize,
        tsc_freq: u64,
    ) -> Self {
        let operation_class = operation.operation_class_label(payload_size);
        let slots = OperationSlots::new_with_payload(max_submitted, operation, payload_size);

        Self {
            wq,
            slots,
            seen: vec![false; max_submitted],
            sentinel_comp: DsaCompletionRecord::default(),
            operation_class,
            tsc_freq,
        }
    }

    fn operation_class(&self) -> &str {
        &self.operation_class
    }

    fn collect_result(
        &mut self,
        k_prefill: usize,
        submitted: usize,
        iterations: usize,
    ) -> SubmitOccupancyResult {
        let mut prefill_completion_trace = Vec::with_capacity(iterations);
        let mut extra_submit_trace = Vec::with_capacity(iterations * (submitted - k_prefill));
        let mut trace_outcomes = Vec::with_capacity(iterations);

        for iteration_index in 0..iterations {
            self.run_iteration(
                k_prefill,
                submitted,
                iteration_index,
                &mut extra_submit_trace,
                &mut trace_outcomes,
                &mut prefill_completion_trace,
            );
        }

        SubmitOccupancyResult {
            benchmark: SUBMIT_OCCUPANCY_BENCHMARK.to_string(),
            operation_class: self.operation_class.clone(),
            k_prefill,
            submitted,
            trace_until: submitted,
            prefill_completion_trace,
            extra_submit_trace,
            trace_outcomes,
        }
    }

    fn run_iteration(
        &mut self,
        k_prefill: usize,
        submitted: usize,
        iteration_index: usize,
        extra_submit_trace: &mut Vec<SubmitOccupancyExtraTracePoint>,
        trace_outcomes: &mut Vec<SubmitOccupancyTraceOutcome>,
        prefill_completion_trace: &mut Vec<SubmitOccupancyPrefillCompletionTracePoint>,
    ) {
        reset_sample_completions(&mut self.slots.completions[..submitted]);
        submit_descriptors(self.wq, &self.slots.descriptors[..k_prefill]);
        self.trace_measured_submits(k_prefill, submitted, iteration_index, extra_submit_trace);

        let outcome = self.completion_outcome(submitted, k_prefill, iteration_index);
        trace_outcomes.push(outcome);

        let prefill_completion = self.measure_prefill_completion(k_prefill, iteration_index);
        prefill_completion_trace.push(prefill_completion);
        if k_prefill > 0 {
            self.drain(k_prefill);
        }
    }

    fn trace_measured_submits(
        &self,
        k_prefill: usize,
        submitted: usize,
        iteration_index: usize,
        extra_submit_trace: &mut Vec<SubmitOccupancyExtraTracePoint>,
    ) {
        for submit_index in k_prefill..submitted {
            let start_tsc = rdtscp().0;
            unsafe { self.wq.submit(&self.slots.descriptors[submit_index]) };
            let submit_tsc_ticks = rdtscp().0 - start_tsc;
            extra_submit_trace.push(SubmitOccupancyExtraTracePoint {
                iteration_index,
                submit_index,
                submit_tsc_ticks,
                submit_ns: cycles_to_ns(submit_tsc_ticks, self.tsc_freq),
            });
        }
    }

    fn completion_outcome(
        &mut self,
        submitted: usize,
        k_prefill: usize,
        iteration_index: usize,
    ) -> SubmitOccupancyTraceOutcome {
        let bounded_outcome = count_visible_completions(
            &self.slots.completions[..submitted],
            &mut self.seen[..submitted],
        );

        self.drain(k_prefill);

        let outcome = if bounded_outcome.completed == submitted {
            bounded_outcome
        } else {
            scan_visible_completions(&self.slots.completions[..submitted])
        };

        SubmitOccupancyTraceOutcome {
            iteration_index,
            completed: outcome.completed,
            missing: submitted - outcome.completed,
            errors: outcome.errors,
        }
    }

    fn measure_prefill_completion(
        &mut self,
        k_prefill: usize,
        iteration_index: usize,
    ) -> SubmitOccupancyPrefillCompletionTracePoint {
        measure_prefill_completion_trace(
            self.wq,
            &self.slots.descriptors[..k_prefill],
            &mut self.slots.completions[..k_prefill],
            &mut self.seen[..k_prefill],
            self.tsc_freq,
            iteration_index,
        )
    }

    fn drain(&mut self, k_prefill: usize) {
        drain_with_sentinel(
            self.wq,
            &mut self.sentinel_comp,
            &self.operation_class,
            k_prefill,
        );
    }
}

fn submit_descriptors(wq: &WqPortal, descriptors: &[DsaHwDesc]) {
    for desc in descriptors {
        unsafe { wq.submit(desc) };
    }
}

fn empty_prefill_completion_trace_point(
    iteration_index: usize,
) -> SubmitOccupancyPrefillCompletionTracePoint {
    SubmitOccupancyPrefillCompletionTracePoint {
        iteration_index,
        prefill_submit_tsc_ticks: 0,
        prefill_submit_ns: 0,
        prefill_completion_tsc_ticks: 0,
        prefill_completion_ns: 0,
        post_submit_completion_tsc_ticks: 0,
        post_submit_completion_ns: 0,
        completed: 0,
        missing: 0,
        errors: 0,
    }
}

fn measure_prefill_completion_trace(
    wq: &WqPortal,
    descriptors: &[DsaHwDesc],
    completions: &mut [DsaCompletionRecord],
    seen: &mut [bool],
    tsc_freq: u64,
    iteration_index: usize,
) -> SubmitOccupancyPrefillCompletionTracePoint {
    reset_sample_completions(completions);

    if descriptors.is_empty() {
        return empty_prefill_completion_trace_point(iteration_index);
    }

    let prefill_start_tsc = rdtscp().0;
    submit_descriptors(wq, descriptors);
    let prefill_submit_tsc_ticks = rdtscp().0 - prefill_start_tsc;

    let outcome = count_visible_completions(completions, seen);
    let prefill_completion_tsc_ticks = rdtscp().0 - prefill_start_tsc;
    let post_submit_completion_tsc_ticks =
        prefill_completion_tsc_ticks.saturating_sub(prefill_submit_tsc_ticks);

    SubmitOccupancyPrefillCompletionTracePoint {
        iteration_index,
        prefill_submit_tsc_ticks,
        prefill_submit_ns: cycles_to_ns(prefill_submit_tsc_ticks, tsc_freq),
        prefill_completion_tsc_ticks,
        prefill_completion_ns: cycles_to_ns(prefill_completion_tsc_ticks, tsc_freq),
        post_submit_completion_tsc_ticks,
        post_submit_completion_ns: cycles_to_ns(post_submit_completion_tsc_ticks, tsc_freq),
        completed: outcome.completed,
        missing: completions.len() - outcome.completed,
        errors: outcome.errors,
    }
}

fn drain_with_sentinel(
    wq: &WqPortal,
    sentinel_comp: &mut DsaCompletionRecord,
    operation_class: &str,
    k_prefill: usize,
) {
    let mut sentinel_desc = DsaHwDesc::default();
    sentinel_desc.fill_noop(completion_flags_no_cache_control());
    reset_completion(sentinel_comp);
    sentinel_desc.set_completion(sentinel_comp);

    unsafe { wq.submit(&sentinel_desc) };
    let status = poll_completion(sentinel_comp);
    if status != DSA_COMP_SUCCESS {
        panic!(
            "DSA submit-occupancy drain sentinel failed: status {status:#x} \
             (operation={operation_class}, k_prefill={k_prefill})"
        );
    }
}

fn print_trace_header(operation_class: &str) {
    println!("\n=== {SUBMIT_OCCUPANCY_BENCHMARK} ({operation_class}) ===");
    println!(
        "{:>8} {:>10} {:>15} {:>12} {:>12}",
        "K", "submitted", "prefill_samples", "trace_points", "iterations"
    );
}

fn print_trace_row(result: &SubmitOccupancyResult) {
    println!(
