    println!("\n=== {SUBMIT_OCCUPANCY_BENCHMARK} ({operation_class}) ===");
    println!(
        "{:>8} {:>10} {:>15} {:>12} {:>12}",
        "K", "submitted", "prefill_samples", "trace_points", "iterations"
    );
}

